/**
 * @description TEMPLATE response handler. Rename it, set targetField (or replace apply() with your own process),
 * then type the class name in the event's Response Handler Class field. It runs after the immediate reply and again
 * after the callback. Status and External Reference Id are already set by Integration Hub; use this for anything more.
 * With Business Data In Response checked on the event, it runs in a background job: ctx.data holds the "data" object
 * of the answer or callback, and the line you put in ctx.result is shown as Business Result. A handler can run more
 * than once on the same data (Rerun handler, a repeated callback), so update or upsert by an external key; never
 * insert blindly. An exception marks Business Status Failed; the delivery Status is not changed.
 * @group Integration Hub
 */
public with sharing class IH_SampleResponseHandler implements IntegrationHub.IResponseHandler {

    /**
     * Field on the sent record that gets the "reference" from the reply or callback, e.g. 'External_Id__c'.
     * Blank: nothing is updated.
     */
    @TestVisible
    private static String targetField = null;

    /**
     * @description Reads the reply or callback and copies the reference to the sent record.
     * @param ctx the reply or callback
     */
    public void handle(IntegrationHub.ResponseContext ctx) {
        Map<String, Object> reply = parse(ctx == null ? null : ctx.body);
        if (reply == null || ctx.relatedRecordId == null) {
            return;
        }
        Object reference = reply.get('reference');
        if (reference != null && String.isNotBlank(targetField)) {
            apply(ctx.relatedRecordId, targetField, String.valueOf(reference));
        }
        Map<String, Object> data = ctx.data == null ? new Map<String, Object>() : ctx.data;
        /* Business data example: the answer {"status":"SUCCESS","reference":"V-1","data":{"shipments":[{"number":"S-1"}]}}.
           Upsert by an external key so a rerun updates the same rows instead of adding new ones:
             List<Shipment__c> rows = new List<Shipment__c>();
             for (Object item : (List<Object>) data.get('shipments')) {
                 Map<String, Object> s = (Map<String, Object>) item;
                 rows.add(new Shipment__c(Shipment_Number__c = (String) s.get('number'), Case__c = ctx.relatedRecordId));
             }
             IntegrationHubData.upsertAll(rows, Shipment__c.Shipment_Number__c);
             ctx.result = rows.size() + ' shipments saved';
           Shipment__c and Shipment_Number__c (an External Id field) stand for your own object and key. */
        ctx.result = 'Reference ' + reference + (data.isEmpty() ? '' : ', data keys: ' + String.join(new List<String>(data.keySet()), ', '));
    }

    /**
     * @description The reply as a JSON object.
     * @param body the reply text
     * @return the object, or null when the text is blank, not JSON or not an object
     */
    @TestVisible
    private static Map<String, Object> parse(String body) {
        if (String.isBlank(body)) {
            return null;
        }
        try {
            Object parsed = JSON.deserializeUntyped(body);
            return parsed instanceof Map<String, Object> ? (Map<String, Object>) parsed : null;
        } catch (JSONException e) {
            return null;
        }
    }

    /**
     * @description Sets one field on the sent record, in system mode.
     * @param recordId the sent record
     * @param fieldName the field API name
     * @param value the value
     */
    @TestVisible
    private static void apply(Id recordId, String fieldName, String value) {
        SObject rec = recordId.getSObjectType().newSObject(recordId);
        rec.put(fieldName, value);
        new Elevated().save(rec);
    }

    /**
     * @description Saves in system mode: the user whose action sent the record may not edit it.
     */
    private without sharing class Elevated {

        void save(SObject rec) {
            update as system rec;
        }
    }
}
